excels.excel:

EXPORT WITH SHEET="研发项目里程碑进度表", HEADER=true,
    MAPPING={"a":"里程碑阶段","b":"负责人","c":"计划工时","d":"实际工时","e":"偏差工时","f":"工时达成率","g":"状态"},
    FORMAT={"c":"#,##0","d":"#,##0","e":"#,##0","f":"0.00%"},
    FORMULAS={
        E2:'C2-D2',F2:'C2/D2',E3:'C3-D3',F3:'C3/D3',
        E4:'C4-D4',F4:'C4/D4',E5:'C5-D5',F5:'C5/D5',
        E6:'C6-D6',F6:'C6/D6',
        C7:'SUM(C2:C6)',D7:'SUM(D2:D6)',E7:'C7-D7',F7:'C7/D7'
    },
    STYLE={
        ROW 7:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        F3:{color:red,bold:true}
    }
